SELECT #{push} time,proto_type type,SUM(c2s_byte_len)+SUM(s2c_byte_len) count
FROM traffic_protocol_statistic
  WHERE stat_time >= #{start}
  AND stat_time < #{end}
GROUP BY proto_type;


select #{push} time,proto_type type,max(link_num) linknum ,sum(c2s_pkt_num)+sum(s2c_pkt_num) pakeagenum,
sum(c2s_byte_len)+sum(s2c_byte_len) bytes
FROM traffic_protocol_statistic
    WHERE stat_time >= #{start}
    AND stat_time < #{end}
GROUP BY proto_type


SELECT #{push} time ,ip_addr ip,area_id area,max(link_num) links,sum(c2s_pkt_num+s2c_pkt_num) packets,
 sum(c2s_byte_len+s2c_byte_len) bytes
 FROM traffic_ip_active_statistic
 WHERE stat_time >= #{start}
 AND stat_time < #{end}
 group by ip_addr,area_id


        SELECT #{push} time,t.port port ,avg(t.speed)  bps
        from ( SELECT RECV_TIME,PORT_DESC port,INOCTETS_SPEED+OUTOCTETS_SPEED as speed
               FROM traffic_netflow_port_info
              where RECV_TIME >= #{start}
			  and RECV_TIME < #{end} ) t
         GROUP BY port;


